# Artifact: tool/check_expense_limit.py

"""
Tool to check if an expense claim amount is within Acme's policy limits.

Validates expense amounts against predefined policy limits for different
categories. Use this tool when employees need to verify if their expense
is within the approved limit before submitting a claim.
"""


def check_expense_limit(category: str, amount: float, currency: str = "USD") -> dict:
    """
    Check if an expense amount is within Acme's policy limit for the given category.
    
    Use this tool to validate expense claims against company policy limits.
    It helps employees understand if their expense requires special approval
    or if it falls within standard limits.
    
    Args:
        category: The expense category. Valid values are:
            - "meals" or "meal"
            - "lodging" or "hotel"
            - "transportation" or "ground_transportation"
            - "airfare" or "flight"
            - "office_supplies" or "supplies"
            - "conference" or "training"
            - "miscellaneous" or "other"
        amount: The expense amount to check
        currency: Currency code (default: "USD"). Currently only USD is supported.
    
    Returns:
        dict: A result dictionary containing:
            - status: "success" or "error"
            - within_limit: boolean indicating if amount is within policy (success only)
            - limit: the applicable policy limit (success only)
            - limit_type: description of the limit (success only)
            - message: guidance message about the expense
            - error_message: error description (error only)
    """
    try:
        # Normalize category input
        category_lower = category.lower().strip()
        
        # Only USD is supported in this version
        if currency.upper() != "USD":
            return {
                "status": "error",
                "error_message": f"Currency '{currency}' is not supported. Only USD is currently supported."
            }
        
        # Validate amount
        if amount < 0:
            return {
                "status": "error",
                "error_message": "Amount cannot be negative."
            }
        
        # Define policy limits
        # Format: (limit_amount, limit_description, requires_preapproval, context_question)
        policy_rules = {
            "meals": {
                "domestic": (75.0, "$75 per day for domestic travel"),
                "international": (100.0, "$100 per day for international travel")
            },
            "meal": {
                "domestic": (75.0, "$75 per day for domestic travel"),
                "international": (100.0, "$100 per day for international travel")
            },
            "lodging": {
                "domestic": (200.0, "$200 per night for domestic travel"),
                "international": (300.0, "$300 per night for international travel")
            },
            "hotel": {
                "domestic": (200.0, "$200 per night for domestic travel"),
                "international": (300.0, "$300 per night for international travel")
            },
            "transportation": (100.0, "$100 per day (taxis, rideshare, parking)", False),
            "ground_transportation": (100.0, "$100 per day (taxis, rideshare, parking)", False),
            "airfare": (500.0, "requires pre-approval for amounts over $500", True),
            "flight": (500.0, "requires pre-approval for amounts over $500", True),
            "office_supplies": (50.0, "$50 per transaction", False),
            "supplies": (50.0, "$50 per transaction", False),
            "conference": (0.0, "requires manager approval for any amount", True),
            "training": (0.0, "requires manager approval for any amount", True),
            "miscellaneous": (25.0, "$25 per transaction", False),
            "other": (25.0, "$25 per transaction", False)
        }
        
        # Check if category is valid
        if category_lower not in policy_rules:
            valid_categories = sorted(set([
                "meals", "lodging", "transportation", "airfare", 
                "office_supplies", "conference", "miscellaneous"
            ]))
            return {
                "status": "error",
                "error_message": f"Unknown category '{category}'. Valid categories are: {', '.join(valid_categories)}"
            }
        
        # Get policy rule for the category
        rule = policy_rules[category_lower]
        
        # Handle categories with domestic/international split
        if isinstance(rule, dict):
            # These categories need clarification about domestic vs international
            domestic_limit, domestic_desc = rule["domestic"]
            international_limit, international_desc = rule["international"]
            
            # Check against the more permissive international limit
            if amount <= international_limit:
                within_limit = True
                if amount <= domestic_limit:
                    message = (
                        f"✓ ${amount:.2f} is within the policy limit. "
                        f"This amount is within limits for both domestic ({domestic_desc}) "
                        f"and international ({international_desc}) travel."
                    )
                    limit_used = domestic_limit
                    limit_desc = domestic_desc
                else:
                    message = (
                        f"✓ ${amount:.2f} is within the policy limit for international travel ({international_desc}). "
                        f"Note: This exceeds the domestic limit ({domestic_desc}). "
                        f"Make sure to indicate this is for international travel when submitting."
                    )
                    limit_used = international_limit
                    limit_desc = international_desc
            else:
                within_limit = False
                message = (
                    f"✗ ${amount:.2f} exceeds policy limits. "
                    f"Domestic limit: {domestic_desc}. International limit: {international_desc}. "
                    f"This expense will require manager approval and justification."
                )
                limit_used = international_limit
                limit_desc = f"Domestic: {domestic_desc}, International: {international_desc}"
        
        # Handle categories with pre-approval requirements
        elif len(rule) > 2 and rule[2]:  # Has pre-approval flag set to True
            limit_amount, limit_desc, requires_preapproval = rule
            
            if category_lower in ["conference", "training"]:
                # Conference/training always requires approval
                within_limit = False
                message = (
                    f"Conference and training expenses require manager approval regardless of amount. "
                    f"Your ${amount:.2f} expense should be submitted with manager pre-approval."
                )
                limit_used = 0.0
            else:
                # Airfare case
                if amount <= limit_amount:
                    within_limit = True
                    message = f"✓ ${amount:.2f} is within the standard limit ({limit_desc}). No pre-approval needed."
                    limit_used = limit_amount
                else:
                    within_limit = False
                    message = (
                        f"✗ ${amount:.2f} exceeds ${limit_amount:.2f}. "
                        f"This {category_lower} expense requires pre-approval. "
                        f"Please obtain manager approval before booking."
                    )
                    limit_used = limit_amount
        
        # Handle simple limit categories
        else:
            limit_amount, limit_desc, _ = rule if len(rule) > 2 else (*rule, False)
            
            if amount <= limit_amount:
                within_limit = True
                message = f"✓ ${amount:.2f} is within the policy limit ({limit_desc})."
                limit_used = limit_amount
            else:
                within_limit = False
                over_by = amount - limit_amount
                message = (
                    f"✗ ${amount:.2f} exceeds the policy limit ({limit_desc}) by ${over_by:.2f}. "
                    f"This expense will require manager approval and justification."
                )
                limit_used = limit_amount
        
        return {
            "status": "success",
            "within_limit": within_limit,
            "limit": limit_used,
            "limit_type": limit_desc,
            "message": message,
            "category": category_lower,
            "amount": amount,
            "currency": currency
        }
    
    except Exception as e:
        return {
            "status": "error",
            "error_message": f"An error occurred while checking the expense limit: {str(e)}"
        }
